import React, { useEffect, useState } from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import SEO from "../../../components/seo";
import enLocale from "../../../locales/en/index.json";
import frLocale from "../../../locales/fr/index.json";
import esLocale from "../../../locales/es/index.json";

type Lang = "en" | "fr" | "es";

const TRANSLATIONS: Record<Lang, typeof enLocale> = {
  en: enLocale,
  fr: frLocale,
  es: esLocale,
};

function useSurveyTranslation(lang: Lang) {
  return (key: string): string => {
    const keys = key.split(".");
    let val: unknown = TRANSLATIONS[lang];
    for (const k of keys) val = (val as Record<string, unknown>)?.[k];
    return typeof val === "string" ? val : key;
  };
}
import rawData from "../../../data/data.json";
import images from "../../../images";
import {
  getItineraryBySurveyToken,
  createSatisfactionResponse,
} from "../../../sessionServices/surveys/satisfactionService";

const companyData = {
  companyName: rawData.name,
  address: rawData.address,
  city: rawData.city,
  province: rawData.province,
  country: "Canada",
  phone: rawData.phone,
  email: rawData.email,
  instagram: rawData.instagram,
  facebook: rawData.facebook,
  linkedin: "",
  postalCode: rawData.postalCode,
  url: rawData.url,
  whatsapp: "",
  menu: rawData.menu,
};

const GOOGLE_REVIEW_URL = "https://g.page/r/REPLACE_WITH_YOUR_PLACE_ID/review";

const LANGS = [
  { code: "en", label: "English" },
  { code: "fr", label: "Français" },
  { code: "es", label: "Español" },
] as const;

// ─── Star rating component ────────────────────────────────────────────────────
function StarRating({
  value,
  onChange,
}: {
  value: number;
  onChange: (v: number) => void;
}) {
  const [hovered, setHovered] = useState(0);
  return (
    <div className="flex gap-1" role="group">
      {[1, 2, 3, 4, 5].map((star) => (
        <button
          key={star}
          type="button"
          onClick={() => onChange(star)}
          onMouseEnter={() => setHovered(star)}
          onMouseLeave={() => setHovered(0)}
          className="text-2xl leading-none transition-transform hover:scale-110 focus:outline-none"
          aria-label={`${star} star${star > 1 ? "s" : ""}`}
        >
          <span className={star <= (hovered || value) ? "text-amber-400" : "text-gray-300"}>
            ★
          </span>
        </button>
      ))}
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function SurveyPage({ params }: PageProps) {
  const token = params["token"] ?? "";
  const [lang, setLang] = useState<Lang>("es");
  const t = useSurveyTranslation(lang);

  const [itineraryId, setItineraryId] = useState<string | undefined>();
  const [loadState, setLoadState] = useState<"loading" | "ready" | "notFound">("loading");
  const [submitted, setSubmitted] = useState(false);
  const [alreadySubmitted, setAlreadySubmitted] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [ratings, setRatings] = useState({ q1: 0, q2: 0, q3: 0, q4: 0, q5: 0, q6: 0 });
  const [texts, setTexts] = useState({ q7: "", q8: "", q9: "" });

  useEffect(() => {
    if (!token) { setLoadState("notFound"); return; }

    const browserLang = navigator.language.slice(0, 2);
    if (["en", "fr", "es"].includes(browserLang)) setLang(browserLang as Lang);

    if (localStorage.getItem(`survey_submitted_${token}`)) {
      setAlreadySubmitted(true);
      setLoadState("ready");
      return;
    }

    if (token === "general") { setLoadState("ready"); return; }

    getItineraryBySurveyToken(token).then((it) => {
      if (!it) { setLoadState("notFound"); }
      else { setItineraryId(it.id); setLoadState("ready"); }
    });
  }, [token]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    if (Object.values(ratings).some((v) => v === 0)) {
      setError(t("survey.ratingRequired"));
      return;
    }
    setSubmitting(true);
    try {
      await createSatisfactionResponse({
        itineraryId,
        surveyToken: token,
        lang,
        ...ratings,
        ...texts,
      });
      localStorage.setItem(`survey_submitted_${token}`, "1");
      setSubmitted(true);
    } catch {
      setError(t("survey.errorSubmit"));
    } finally {
      setSubmitting(false);
    }
  }

  if (loadState === "loading") {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (loadState === "notFound") {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4">
        <p className="text-center text-sm text-gray-500">{t("survey.notFound")}</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 px-4 py-10">
      <header className="mb-6 flex items-center gap-3 justify-center">
        <img src={images.logo.src} alt={images.logo.alt} className="h-10 w-auto" />
        <p className="text-lg font-semibold text-gray-900">Jenny Adventures</p>
      </header>
      <div className="mx-auto max-w-xl">
        {/* Language selector */}
        <div className="mb-6 flex justify-end gap-2">
          {LANGS.map(({ code, label }) => (
            <button
              key={code}
              onClick={() => setLang(code)}
              className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
                lang === code
                  ? "bg-gray-900 text-white"
                  : "bg-white text-gray-500 ring-1 ring-gray-200 hover:bg-gray-100"
              }`}
            >
              {label}
            </button>
          ))}
        </div>

        {alreadySubmitted ? (
          <div className="rounded-2xl bg-white p-8 shadow-sm ring-1 ring-gray-100 text-center">
            <div className="mb-4 text-4xl">✓</div>
            <p className="text-sm text-gray-600">{t("survey.alreadySubmitted")}</p>
          </div>
        ) : submitted ? (
          <div className="rounded-2xl bg-white p-8 shadow-sm ring-1 ring-gray-100 text-center">
            <div className="mb-4 text-5xl">🌟</div>
            <h2 className="mb-3 text-xl font-bold text-gray-900">{t("survey.thankYouTitle")}</h2>
            <p className="mb-8 text-sm text-gray-600 leading-relaxed">{t("survey.thankYouBody")}</p>
            <div className="rounded-xl bg-amber-50 p-5">
              <p className="mb-3 text-xs text-amber-700 leading-relaxed">{t("survey.reviewNote")}</p>
              <a
                href={GOOGLE_REVIEW_URL}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block rounded-lg bg-amber-500 px-6 py-2.5 text-sm font-semibold text-white hover:bg-amber-600 transition-colors"
              >
                {t("survey.reviewCta")} ★
              </a>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Header */}
            <div className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-gray-100">
              {/* <h1 className="mb-1 text-xl font-bold text-gray-900">Jenny Adventures</h1> */}
              <p className="text-sm text-gray-600 leading-relaxed">{t("survey.intro")}</p>
              <p className="mt-3 text-xs text-gray-400">
                {t("survey.ratingLabel")} · {t("survey.ratingHint")}
              </p>
            </div>

            {/* Star questions */}
            <div className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-gray-100 space-y-5">
              {(["q1", "q2", "q3", "q4", "q5", "q6"] as const).map((key, i) => (
                <div key={key}>
                  <p className="mb-2 text-sm font-medium text-gray-800">
                    <span className="mr-1.5 text-gray-400">{i + 1}.</span>
                    {t(`survey.${key}`)}
                  </p>
                  <StarRating
                    value={ratings[key]}
                    onChange={(v) => setRatings((prev) => ({ ...prev, [key]: v }))}
                  />
                </div>
              ))}
            </div>

            {/* Open questions */}
            <div className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-gray-100 space-y-5">
              {(["q7", "q8", "q9"] as const).map((key, i) => {
                const optional = key !== "q7";
                return (
                  <div key={key}>
                    <label className="mb-1.5 block text-sm font-medium text-gray-800">
                      <span className="mr-1.5 text-gray-400">{i + 7}.</span>
                      {t(`survey.${key}`)}
                      {optional && (
                        <span className="ml-1.5 text-xs font-normal text-gray-400">
                          ({t("survey.optional")})
                        </span>
                      )}
                    </label>
                    <textarea
                      rows={3}
                      value={texts[key]}
                      onChange={(e) => setTexts((prev) => ({ ...prev, [key]: e.target.value }))}
                      required={!optional}
                      className="block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800 resize-none"
                    />
                  </div>
                );
              })}
            </div>

            {error && (
              <p className="rounded-lg bg-red-50 px-4 py-2.5 text-xs text-red-700">{error}</p>
            )}

            <button
              type="submit"
              disabled={submitting}
              className="w-full rounded-xl bg-gray-900 py-3 text-sm font-semibold text-white transition-colors hover:bg-gray-700 disabled:opacity-60"
            >
              {submitting ? t("survey.submitting") : t("survey.submit")}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

export const Head: HeadFC = () => (
  <SEO
    data={companyData}
    title="Satisfaction Survey, Jenny Adventures"
    description="Share your feedback about your travel experience with Jenny Adventures."
    pathname="/app/survey"
    noindex
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
